TIP_CAP_TOTAL = {sd: SPEC["coat_depth_limits"]["tip"]["max_total_coat_depth_mm"][sd] for sd in "LR"}


def _unit(x):
    x = np.asarray(x, float); return x / np.linalg.norm(x, axis=-1, keepdims=True)


def _ss(t):
    t = np.clip(t, 0.0, 1.0); return t * t * (3 - 2 * t)


def _smin(a, b, k):
    k = np.maximum(np.asarray(k, float), 1e-9)
    h = np.clip(k - np.abs(a - b), 0, None) / k
    return np.minimum(a, b) - h * h * k / 4


# ---------------------------------------------------------------- per-ear pocket model from the spec tables
class Ear:
    def __init__(self, sd):
        self.sd = sd
        B = np.load(os.path.join(TR, "layers", f"ears_base_{sd}.npz"))
        self.O = PT.head_local(B["origin"][None])[0] * 1000
        self.A = _unit(B["axis"] @ PT.HR); self.l = _unit(B["lateral"] @ PT.HR); self.w = _unit(B["front"] @ PT.HR)
        rows = [r for r in SPEC["tables"][f"pocket_sections_{sd}"] if r["slot_depth_below_free_edge_mm"]]
        rows.sort(key=lambda r: r["h_mm"])
        self.rows = rows
        self.h = np.array([r["h_mm"] for r in rows])
        self.in_slot = np.array([bool(r["in_slot"]) for r in rows])
        self.E = np.array([r["free_edge_head_mm"] for r in rows], float)
        self.Fl = np.array([r["floor_head_mm"] for r in rows], float)
        self.D = np.array([r["slot_depth_below_free_edge_mm"] for r in rows], float)
        self.g50 = np.maximum(np.array([r["wall_gap_50pct_mm"] for r in rows], float), G_MIN)
        self.g90 = np.maximum(np.array([r["wall_gap_90pct_mm"] for r in rows], float), G_MIN)
        m = np.array([r["mouth_direction_head"] for r in rows], float)
        m = m - np.outer(m @ self.A, self.A); self.m = _unit(m)                    # in the section plane
        n = _unit(np.cross(self.A[None], self.m))
        sgn = np.sign(n @ (self.l - self.w)); n *= np.where(sgn == 0, 1, sgn)[:, None]   # toward caudal-lateral (flap)
        self.n = n
        self.lip = np.array([[r["envelope_lip_thickness_mm_at_below_edge"][k] for k in ("0.5", "1.0", "2.0", "3.0")]
                             for r in rows], float)
        self.h_lo, self.h_hi = float(self.h[0]), float(self.h[-1])
        self.BI = np.asarray(WALLS[sd]["b_in"], float); self.BM = np.asarray(WALLS[sd]["b_med"], float)
        s = self.h[self.in_slot]; self.slot_lo, self.slot_hi = float(s.min()), float(s.max())
        self.flap_lo = self.h_lo - 0.5                                               # the flap's island ~0.5 mm lower
        P = np.vstack([self.E, self.Fl])
        self.lo = P.min(0) - 7.0; self.hi = P.max(0) + 7.0

    def interp(self, hq):
        hq = np.clip(hq, self.h_lo, self.h_hi)
        f = lambda y: np.interp(hq, self.h, y)                                       # noqa: E731
        E = np.stack([f(self.E[:, k]) for k in range(3)], -1)
        m = _unit(np.stack([f(self.m[:, k]) for k in range(3)], -1))
        n = _unit(np.stack([f(self.n[:, k]) for k in range(3)], -1))
        return E, m, n, f(self.D), f(self.g50), f(self.g90)

    def walls(self, hq, a, D):
        """Tripo's slot walls at (h, a): b_in (flap inner face), gap g (>= G_MIN), centre c = b_in - g / 2"""
        U = np.asarray(WALLS["U"]); BI = self.BI; BM = self.BM
        x = np.clip(np.interp(hq, self.h, np.arange(len(self.h))), 0, len(self.h) - 1)
        i0 = np.minimum(np.floor(x).astype(int), len(self.h) - 2); fx = x - i0
        y = np.interp(np.clip(a / D, 0, 1), U, np.arange(len(U)))
        j0 = np.minimum(np.floor(y).astype(int), len(U) - 2); fy = y - j0
        bil = lambda M: ((M[i0, j0] * (1 - fy) + M[i0, j0 + 1] * fy) * (1 - fx) +            # noqa: E731
                         (M[i0 + 1, j0] * (1 - fy) + M[i0 + 1, j0 + 1] * fy) * fx)
        bi = bil(BI); g = np.maximum(bi - bil(BM), G_MIN)
        return bi, g, bi - g / 2

    @staticmethod
    def thick(a, D):
        return T_EDGE + (T_ROOT - T_EDGE) * np.clip(a / D, 0, 1)

    def local(self, P):
        hq = (P - self.O) @ self.A
        E, m, n, D, g50, g90 = self.interp(hq)
        r = P - E; r = r - (r * self.A).sum(-1, keepdims=True) * self.A
        return hq, -(r * m).sum(-1), (r * n).sum(-1), D

    def fields(self, P):
        """slot (air SDF, < 0 inside the slot), sheet (flap tissue SDF), zone (< 0 where the base is replaced)"""
        hq, a, b, D = self.local(P)
        bi, g, c = self.walls(hq, a, D)
        _, gD, cD = self.walls(hq, D, D)
        af = D - gD / 2
        s2 = np.where(a <= af, np.abs(b - c) - g / 2, np.hypot(a - af, b - cD) - gD / 2)
        s2 = np.maximum(s2, -MOUTH_OUT - a)
        slot = np.maximum(s2, np.maximum((self.h_lo - 0.25) - hq, hq - (self.h_hi + 0.25)))
        at = T_EDGE / 2; ac = np.maximum(a, at)
        bi_c, _, _ = self.walls(hq, ac, D); t = self.thick(ac, D); bm = bi_c + t / 2
        sh = np.hypot(np.maximum(at - a, 0), b - bm) - t / 2
        sh = np.maximum(sh, a - (D + 1.0))
        sheet = np.maximum(sh, np.maximum(self.flap_lo - hq, hq - (self.h_hi + 0.25)))
        z = np.maximum(c - b, np.maximum(-MOUTH_OUT - a, a - (D + 0.5)))
        z = np.maximum(z, b - (bi_c + t + ZONE_W))
        zone = np.maximum(z, np.maximum((self.flap_lo - 0.25) - hq, hq - (self.h_hi + 0.5)))
        return slot, sheet, zone


EARS = {sd: Ear(sd) for sd in "LR"}
REGION = {sd: (e.lo.copy(), e.hi.copy()) for sd, e in EARS.items()}


def edit(P_head_mm, F_mm, D_mm=None):
    """the pocket edit on the skin field F (head-frame mm, negative inside); returns a new array"""
    P = np.asarray(P_head_mm, float); F = np.array(F_mm, float, copy=True)
    for sd, e in EARS.items():
        b = np.all((P >= e.lo) & (P <= e.hi), axis=1)
        if not b.any():
            continue
        idx = np.nonzero(b)[0]
        for c0 in range(0, len(idx), 1_000_000):
            ii = idx[c0:c0 + 1_000_000]; p = P[ii]; f0 = F[ii]
            slot, sheet, zone = e.fields(p)
            extra = D_CAP - (D_BASE_ASSUMED if D_mm is None else np.asarray(D_mm, float)[ii])
            k = K_ROOT * np.clip((slot - 0.5) / 0.5, 0, 1)
            fz = _smin(sheet, f0 + np.maximum(extra, 0), k)
            w = _ss(0.5 - zone / 1.0)                                  # 1 inside the zone by 0.5 mm, 0 outside by 0.5 mm
            fn = f0 + w * (fz - f0)
            F[ii] = np.maximum(fn, -slot)                              # HARD carve: the slot is air by construction
    return F


# ---------------------------------------------------------------- coat cap for the coat_field owner
def coat_cap_mm(P_head_mm):
    """max PER-FACE coat depth (mm) at P (inf = no cap): ear tip (spec tip table / 2) and the flap free edge"""
    P = np.asarray(P_head_mm, float); cap = np.full(len(P), np.inf)
    for sd, e in EARS.items():
        s = APEX_H[sd] - (P - e.O) @ e.A                                # mm below the envelope apex
        rad = np.linalg.norm((P - e.O) - np.outer((P - e.O) @ e.A, e.A), axis=1)
        tb = TIP_CAP_TOTAL[sd]; ks = np.array(sorted(float(k) for k in tb)); vs = np.array([tb[f"{k:g}"] if f"{k:g}" in tb else tb[str(k)] for k in ks]) / 2
        c = np.interp(np.clip(s, ks[0], ks[-1]), ks, vs)
        far = _ss((s - ks[-1]) / 4.0)                                   # 0 at 4 mm -> 1 at 8 mm below the apex
        on = (s > -3) & (rad < 25)
        cs = np.where(far >= 1, np.inf, c / np.maximum(1 - far, 1e-6))  # cap grows without bound by 8 mm
        cap[on] = np.minimum(cap[on], cs[on])
        # flap free edge: outer-face depth <= FLAP_EDGE_CAP within 1 mm of the free edge, released by 3 mm
        b = np.all((P >= e.lo) & (P <= e.hi), axis=1)
        if b.any():
            hq, a, bb, D = e.local(P[b])
            near = (hq >= e.flap_lo - 0.5) & (hq <= e.h_hi + 0.5) & (a > -2) & (a < 3)
            ce = np.where(a <= 1.0, FLAP_EDGE_CAP, FLAP_EDGE_CAP / np.maximum(1 - _ss((a - 1.0) / 2.0), 1e-6))
            sub = cap[b]; sub[near] = np.minimum(sub[near], ce[near]); cap[b] = sub
    return cap


def skin_cap_apply(d, cap, k=0.1):
    """smooth min(d, cap) (C3b: no crease where the cap starts)"""
    d = np.asarray(d, float); cap = np.asarray(cap, float)
    out = d.copy(); fin = np.isfinite(cap)
    out[fin] = _smin(d[fin], cap[fin], k)
    return np.maximum(out, 0.0)


# ---------------------------------------------------------------- probes (mesh vertices in head-frame mm)
def _all_hits(O, Dv, tri, maxd=2.5):
    """every crossing t (sorted) of the line O + t Dv with triangles tri near the line (centroid within maxd + edge)"""
    C = tri.mean(1); r = C - O; along = r @ Dv; perp = np.linalg.norm(r - np.outer(along, Dv), axis=1)
    rad = np.linalg.norm(tri - C[:, None], axis=2).max(1)
    sel = perp < maxd + rad
    T = tri[sel]
    if not len(T):
        return np.zeros(0)
    v0 = T[:, 0]; e1 = T[:, 1] - v0; e2 = T[:, 2] - v0
    p = np.cross(Dv, e2); det = (e1 * p).sum(1); ok = np.abs(det) > 1e-12; inv = np.where(ok, 1 / np.where(ok, det, 1), 0)
    s = O - v0; u = (s * p).sum(1) * inv; q = np.cross(s, e1); vv = (q * Dv).sum(1) * inv; t = (e2 * q).sum(1) * inv
    hit = ok & (u >= 0) & (vv >= 0) & (u + vv <= 1)
    th = np.sort(t[hit])
    if len(th) > 1:                                      # a crossing on a shared edge counts once
        th = th[np.r_[True, np.diff(th) > 1e-7]]
    return th


def _intervals(O, Dv, tri, L):
    """inside-tissue intervals [t0, t1] along O + t Dv, O assumed OUTSIDE (far start), parity rule; an unpaired last
    crossing (the line ends inside, e.g. in the skull) closes at +inf"""
    th = _all_hits(O, Dv, tri); th = th[th > 0]
    odd = len(th) % 2
    if odd:
        th = np.r_[th, np.inf]
    iv = [(th[i], th[i + 1]) for i in range(0, len(th) - 1, 2)]
    return [(a, b) for a, b in iv if b > 0 and a < L], odd


def _row(e, hq):
    E, m, n, D, g50, g90 = e.interp(np.array([hq]))
    return E[0], m[0], n[0], float(D[0])


def _across(e, tri, hq, a, far=40.0, win=1.5):
    """air / tissue reading across the slot at depth a below the free edge, section h (in b coords)"""
    E, m, n, D = _row(e, hq)
    O = E - a * m + far * n
    iv, odd = _intervals(O, -n, tri, 2 * far)
    tis = sorted([(far - t1, far - t0) for t0, t1 in iv], key=lambda x: -x[1])     # (lo, hi), lateral first
    _, g_ref, c = e.walls(np.array([hq]), np.array([a]), np.array([D])); c = float(c[0])
    best = None
    for i in range(len(tis) - 1):
        lo_air, hi_air = tis[i + 1][1], tis[i][0]
        dist = 0.0 if lo_air <= c <= hi_air else min(abs(c - lo_air), abs(c - hi_air))
        if dist <= win and (best is None or dist < best[0]):
            best = (dist, i, lo_air, hi_air)
    out = {"a": round(a, 3), "c_ref": round(c, 3), "odd": int(odd), "n_tissue": len(tis),
           "mid_in_tissue": any(lo <= c <= hi for lo, hi in tis)}
    if best is None:
        out.update(slot=False); return out
    _, i, lo_air, hi_air = best
    out.update(slot=True, gap=round(hi_air - lo_air, 3), flap_thick=round(tis[i][1] - tis[i][0], 3),
               slot_centre=round((lo_air + hi_air) / 2, 3))
    return out


def _depth_ray(e, tri, hq, x50):
    """slot depth below the free edge: a ray from the measured slot centre at 50 % depth toward the slot centre at
    the floor (Tripo's walls), first tissue hit = the floor; None if the 50 % point is in tissue"""
    if not x50.get("slot") or x50["mid_in_tissue"]:
        return None
    E, m, n, D = _row(e, hq)
    p0 = E - 0.5 * D * m + x50["slot_centre"] * n
    _, _, cD = e.walls(np.array([hq]), np.array([D]), np.array([D]))
    p1 = E - D * m + float(cD[0]) * n
    Dv = _unit(p1 - p0); iv, _ = _intervals(p0 - 0.0 * Dv, Dv, tri, 40.0)
    # p0 is in air: the first crossing is an entry
    th = _all_hits(p0, Dv, tri); th = th[th > 1e-6]
    if not len(th):
        return float("inf")
    pf = p0 + th[0] * Dv
    return float(-(pf - E) @ m)


def _free_edge(e, tri, hq, far=40.0):
    """the flap's free edge: along -m at the flap's mid-sheet offset, a of the first tissue entry"""
    E, m, n, D = _row(e, hq)
    bi, _, _ = e.walls(np.array([hq]), np.array([T_EDGE / 2]), np.array([D]))
    O = E + (float(bi[0]) + T_EDGE / 2) * n + far * m
    iv, _ = _intervals(O, -m, tri, far + 3.0)
    if not iv:
        return None
    return float(iv[0][0] - far)


def pocket_probe(Lmm, f, inp, sd):
    """C6b / P1 with check_ears B1's fix. Per slot height (0.25 mm): across lines (from 40 mm lateral, parity) at
    a = D/2 (two layers + open), at a = 0.5, 1, 2, 3 (flap tissue thickness), at a = D/2 (flap thinner than Tripo's
    lip by >= 2 mm), a depth ray along the slot midline chord, the free edge along -m.
    PASS = all of: two layers at >= 90 % of heights and at every height within 2 mm of the deepest; slot air >= 0.25
    mm at 50 % and 90 % depth at >= 90 % of heights, the midline at 50 % in air; depth = table +-0.5 at >= 90 % and
    max depth = the reference +-0.5; flap thickness in [0.4, 1.1] mm at a = 0.5..3 at >= 90 % of (height, a); at D/2
    <= Tripo's lip extrapolated - 2.0 mm at >= 90 %; free edge within 0.5 mm of the envelope's at >= 90 %."""
    e = EARS[sd]
    c = np.vstack([e.E, e.Fl]).mean(0)
    keep = np.linalg.norm(Lmm[f].mean(1) - c, axis=1) < 32.0
    tri = Lmm[f[keep]]
    hs = e.h[e.in_slot]; deep_h = float(e.h[np.argmax(e.D)])
    rows = []
    for hq in hs:
        i = int(np.argmin(np.abs(e.h - hq))); D = float(e.D[i])
        r = {"h": float(hq), "D_ref": round(D, 3)}
        x50 = _across(e, tri, hq, 0.5 * D); x90 = _across(e, tri, hq, 0.9 * D)
        r["two_layers"] = bool(x50["slot"] and x50["n_tissue"] >= 2)
        r["gap50"] = x50.get("gap"); r["gap90"] = x90.get("gap")
        r["mid50_in_tissue"] = bool(x50["mid_in_tissue"])
        th = {}
        for a in (0.5, 1.0, 2.0, 3.0):
            if a < D - 0.5:
                x = _across(e, tri, hq, a); th[f"{a:g}"] = x.get("flap_thick")
        r["flap_thick"] = th
        lipfit = np.polyfit([0.5, 1, 2, 3], e.lip[i], 1); lip_half = float(np.polyval(lipfit, 0.5 * D))
        r["flap_thick_D2"] = x50.get("flap_thick"); r["lip_env_D2_extrap"] = round(lip_half, 2)
        dm = _depth_ray(e, tri, hq, x50); r["depth"] = None if dm is None else round(dm, 3)
        fe = _free_edge(e, tri, hq); r["free_edge_a"] = None if fe is None else round(fe, 3)
        rows.append(r)
    nh = len(rows)
    frac = lambda xs: float(np.mean(xs)) if len(xs) else 0.0   # noqa: E731
    two = [r["two_layers"] for r in rows]
    near_deep = [r["two_layers"] for r in rows if abs(r["h"] - deep_h) <= 2.0]
    open_ok = [bool(r["gap50"] is not None and r["gap50"] >= 0.25 and r["gap90"] is not None and r["gap90"] >= 0.25
                    and not r["mid50_in_tissue"]) for r in rows]
    dep_ok = [bool(r["depth"] is not None and np.isfinite(r["depth"]) and abs(r["depth"] - r["D_ref"]) <= 0.5) for r in rows]
    dmax = max([r["depth"] for r in rows if r["depth"] is not None and np.isfinite(r["depth"])], default=float("nan"))
    ref_max = float(SPEC["reference_numbers"]["use_as_is_phase1_SOUND"]["pocket_max_depth_mm"][sd])
    th_ok = [bool(v is not None and 0.4 <= v <= 1.1) for r in rows for v in r["flap_thick"].values()]
    d2_ok = [bool(r["flap_thick_D2"] is not None and r["flap_thick_D2"] <= r["lip_env_D2_extrap"] - 2.0) for r in rows]
    fe_ok = [bool(r["free_edge_a"] is not None and abs(r["free_edge_a"]) <= 0.5) for r in rows]
    crit = {
        "two_layers": frac(two) >= 0.9 and all(near_deep),
        "open": frac(open_ok) >= 0.9,
        "depth": frac(dep_ok) >= 0.9 and abs(dmax - ref_max) <= 0.5,
        "flap_thickness_0.5_to_3": frac(th_ok) >= 0.9,
        "flap_thinner_than_tripo_lip_at_D2": frac(d2_ok) >= 0.9,
        "free_edge": frac(fe_ok) >= 0.9,
    }
    ok = all(crit.values())
    fails = [k for k, v in crit.items() if not v]
    tv = [v for r in rows for v in r["flap_thick"].values() if v is not None]
    return {"status": "PASS" if ok else "FAIL", "heights": nh, "criteria": crit,
            "frac": {"two_layers": round(frac(two), 3), "open": round(frac(open_ok), 3), "depth": round(frac(dep_ok), 3),
                     "flap_thickness": round(frac(th_ok), 3), "thinner_D2": round(frac(d2_ok), 3), "free_edge": round(frac(fe_ok), 3)},
            "depth_max_mm": round(dmax, 3), "depth_max_ref_mm": ref_max,
            "flap_thick_p10_p50_p90": [round(float(np.percentile(tv, q)), 3) for q in (10, 50, 90)] if tv else None,
            "rows": rows, "why": "pocket = two skin layers + open slot" if ok else "FAIL: " + ", ".join(fails)}


def tip_probe(Lmm, f, inp, sd):
    """P4 (tip part): the skin apex along the ear axis within 0.5 mm of the envelope apex (APEX_H)"""
    e = EARS[sd]; tip_pt = e.O + APEX_H[sd] * e.A
    V = Lmm[np.unique(f.ravel())] if len(Lmm) > 3 * len(f) else Lmm
    near = np.linalg.norm(V - tip_pt, axis=1) < 15.0
    if not near.any():
        return {"status": "FAIL", "why": "no surface near the ear tip"}
    hmax = float(((V[near] - e.O) @ e.A).max()); ret = APEX_H[sd] - hmax
    ok = ret <= 0.5
    return {"status": "PASS" if ok else "FAIL", "apex_h_mm": round(hmax, 3), "envelope_apex_h_mm": APEX_H[sd],
            "retraction_mm": round(ret, 3), "mark_mm": 0.5, "why": f"skin apex {ret:.2f} mm below the envelope apex"}


PROBES = {}
for _sd in "LR":
    PROBES[f"henrys_pocket.{_sd}"] = (lambda s: (lambda Lmm, f, inp: pocket_probe(Lmm, f, inp, s)))(_sd)
    PROBES[f"ear_tip.{_sd}"] = (lambda s: (lambda Lmm, f, inp: tip_probe(Lmm, f, inp, s)))(_sd)
